const now = Date.now();
const items = $input.all();
const appts = items[0]?.json?.data || items[0]?.json || [];
const window24h = Array.isArray(appts)
  ? appts.filter(a => {
      const apptTs = new Date(`${a.appointment_date}T${a.appointment_time || '00:00:00'}`).getTime();
      const diffHours = (apptTs - now) / 3600000;
      return diffHours >= 23 && diffHours <= 25;
    })
  : [];
return window24h.map(a => ({ json: a }));

